import { createGlobalStyle } from 'styled-components';
export const GlobalStyle = createGlobalStyle `

   @font-face {
    font-family: 'Bebas Neue';
    src: url('../../public/fonts/BebasNeue-Regular.ttf') format('truetype');
    font-weight: 400;
    font-style: normal;
  }

  @font-face {
    font-family: 'PT Sans';
    src: url('../../public/fonts/PTSans-Regular.ttf') format('truetype');
    font-weight: 400;
    font-style: normal;
  }

  @font-face {
    font-family: 'Protest Strike';
    src: url('../../public/fonts/ProtestStrike-Regular.ttf') format('truetype');
    font-weight: 400;
    font-style: normal;
  }

  :root {
    --color-bg: #E5E5E5;
    --color-card: #ffffff;
    --color-dark: #42567A;
    --color-accent-blue: #5454ff;
    --color-accent-pink: #ff4fa3;
    --color-muted: #8792b0;
  }

  * {
    box-sizing: border-box;
  }

  body {
    margin: 0;
    font-family: 'PT Sans', sans-serif;
    background-color: var(--color-bg);
    color: var(--color-dark);
    min-height: 100vh;
    min-width: 100vw;
  }

  #root {
    min-height: 100vh;
  }

  .swiper {
    overflow: visible;
  }
`;
